    const server = new RuntimeServer({
      projectDir: dir,
      mode: "view-records",
      researchDbFactory: (projectDir) => {
        factoryCalls += 1
        opened.current = new TrackingResearchDb(ResearchDb.open(projectDir))
        return opened.current
      },
    })

